import { defineStore } from 'pinia';
import { computed, ref } from 'vue';
import { useAuthStore } from '@/stores/authStore';
import { getDashboard, getDocuments, getNotifications, getTeam, uploadDocument as apiUploadDocument, updateDocument, downloadDocument as apiDownloadDocument, markAllAsRead, } from '@/lib/api';
export const useFacultyDashboardStore = defineStore('facultyDashboard', () => {
    const authStore = useAuthStore();
    const selectedSection = ref('dashboard');
    const team = ref(null);
    const dashboardSummary = ref({
        totalPrograms: 0,
        totalAreas: 0,
        totalEvidence: 0,
        totalCycles: 0,
        compliancePercent: 0,
        readinessPercent: 0,
        pendingReviews: 0,
        overdueTasks: 0,
    });
    const selectedDocuments = ref([]);
    const notifications = ref([]);
    const pipeline = ref([
        { label: 'Faculty Upload', sub: 'Submit evidence documents', done: true, active: false, returned: false },
        { label: 'Area In-Charge Review', sub: 'Documents are reviewed', done: false, active: false, returned: false },
        { label: 'Program Chair Review', sub: 'Awaiting program chair approval', done: false, active: false, returned: false },
        { label: 'Revision Requests', sub: 'Upload requested corrections', done: false, active: false, returned: false },
        { label: 'Final Submission', sub: 'Ready for final endorsement', done: false, active: false, returned: false },
    ]);
    const dashboardProgram = computed(() => {
        if (team.value?.program?.name)
            return team.value.program.name;
        if (authStore.user?.programId)
            return String(authStore.user.programId);
        return 'Faculty Program';
    });
    const dashboardTeamName = computed(() => team.value?.name || 'No Team Assigned');
    const dashboardTeamLead = computed(() => team.value?.program?.chair || team.value?.lead || 'Program Chair');
    const pendingRevisions = computed(() => selectedDocuments.value.filter((doc) => doc.status === 'revision'));
    const unreadCount = computed(() => notifications.value.filter((notification) => !notification.read).length);
    const selectSection = (section) => {
        selectedSection.value = section;
    };
    const normalizeDocument = (doc) => ({
        id: String(doc.id ?? doc.document_id ?? ''),
        title: doc.title || doc.name || 'Untitled Document',
        area: doc.area || doc.category || 'General',
        program: doc.program || doc.program_name || dashboardProgram.value,
        uploadedBy: doc.uploaded_by || doc.uploader || authStore.user?.name || 'Faculty',
        uploadedAt: doc.uploaded_at || doc.created_at || new Date().toISOString(),
        fileName: doc.file_name || doc.filename || undefined,
        size: doc.size || doc.file_size || undefined,
        fileSize: doc.file_size || doc.size || undefined,
        version: Number(doc.version ?? doc.version_number ?? 1),
        status: (doc.status || 'pending'),
        downloadUrl: doc.download_url || doc.downloadUrl || undefined,
    });
    const loadTeam = async () => {
        const userTeamId = authStore.user?.teamId;
        if (!userTeamId) {
            team.value = {
                id: 'unassigned',
                name: 'No team assigned',
                program: {
                    name: dashboardProgram.value,
                    chair: authStore.user?.name || 'Program Chair',
                },
                lead: authStore.user?.name || 'Program Chair',
            };
            return;
        }
        try {
            const data = await getTeam(userTeamId);
            const payload = data?.data || data;
            team.value = {
                ...payload,
                program: payload.program ?? { name: payload.program_name || dashboardProgram.value, chair: payload.chair || dashboardTeamLead.value },
                lead: payload.lead || payload.team_lead || payload.program?.chair || dashboardTeamLead.value,
            };
        }
        catch {
            team.value = {
                id: userTeamId,
                name: 'My Team',
                program: {
                    name: dashboardProgram.value,
                    chair: dashboardTeamLead.value,
                },
                lead: dashboardTeamLead.value,
            };
        }
    };
    const loadDocuments = async () => {
        const params = {};
        if (authStore.user?.teamId)
            params.team_id = authStore.user.teamId;
        if (authStore.user?.programId)
            params.program_id = authStore.user.programId;
        try {
            const data = await getDocuments(params);
            const payload = Array.isArray(data) ? data : data?.data ?? [];
            selectedDocuments.value = payload.map(normalizeDocument);
        }
        catch {
            selectedDocuments.value = [
                {
                    id: '1',
                    title: 'Faculty CV',
                    area: 'Faculty Profile',
                    program: dashboardProgram.value,
                    uploadedBy: authStore.user?.name || 'Faculty',
                    uploadedAt: new Date(Date.now() - 86400000).toISOString(),
                    version: 1,
                    status: 'approved',
                },
                {
                    id: '2',
                    title: 'Course Matrix',
                    area: 'Curriculum',
                    program: dashboardProgram.value,
                    uploadedBy: authStore.user?.name || 'Faculty',
                    uploadedAt: new Date(Date.now() - 172800000).toISOString(),
                    version: 1,
                    status: 'revision',
                },
                {
                    id: '3',
                    title: 'Research Output',
                    area: 'Research & Development',
                    program: dashboardProgram.value,
                    uploadedBy: authStore.user?.name || 'Faculty',
                    uploadedAt: new Date(Date.now() - 259200000).toISOString(),
                    version: 1,
                    status: 'pending',
                },
            ];
        }
    };
    const loadNotifications = async () => {
        try {
            const data = await getNotifications();
            const payload = Array.isArray(data) ? data : data?.data ?? [];
            notifications.value = payload.map((item) => ({
                id: String(item.id),
                userId: String(item.userId ?? item.user_id ?? authStore.user?.id ?? ''),
                title: item.title || item.subject || 'Notification',
                message: item.message || item.body || 'You have a new notification.',
                type: item.type || 'info',
                read: item.read ?? item.is_read ?? false,
                createdAt: item.createdAt || item.created_at || new Date().toISOString(),
            }));
        }
        catch {
            notifications.value = [
                { id: '1', userId: authStore.user?.id || '1', title: 'Document received', message: 'Your uploaded file is under review.', type: 'info', read: false, createdAt: new Date(Date.now() - 3600000).toISOString() },
                { id: '2', userId: authStore.user?.id || '1', title: 'Revision requested', message: 'Please revise and resubmit your latest document.', type: 'warning', read: false, createdAt: new Date(Date.now() - 7200000).toISOString() },
                { id: '3', userId: authStore.user?.id || '1', title: 'Team update', message: 'A new member joined your accreditation team.', type: 'success', read: true, createdAt: new Date(Date.now() - 86400000).toISOString() },
            ];
        }
    };
    const loadDashboard = async () => {
        const params = {};
        if (authStore.user?.teamId)
            params.team_id = authStore.user.teamId;
        if (authStore.user?.programId)
            params.program_id = authStore.user.programId;
        try {
            const data = await getDashboard(params);
            const payload = data?.data || data || {};
            dashboardSummary.value = {
                totalPrograms: payload.totalPrograms ?? payload.total_programs ?? 1,
                totalAreas: payload.totalAreas ?? payload.total_areas ?? 4,
                totalEvidence: payload.totalEvidence ?? payload.total_evidence ?? 12,
                totalCycles: payload.totalCycles ?? payload.total_cycles ?? 2,
                compliancePercent: payload.compliancePercent ?? payload.compliance_percent ?? 78,
                readinessPercent: payload.readinessPercent ?? payload.readiness_percent ?? 66,
                pendingReviews: payload.pendingReviews ?? payload.pending_reviews ?? 3,
                overdueTasks: payload.overdueTasks ?? payload.overdue_tasks ?? 1,
            };
        }
        catch {
            dashboardSummary.value = {
                totalPrograms: 1,
                totalAreas: 4,
                totalEvidence: 8,
                totalCycles: 2,
                compliancePercent: 72,
                readinessPercent: 63,
                pendingReviews: 3,
                overdueTasks: 1,
            };
        }
    };
    const uploadDocument = async (file, metadata = {}) => {
        try {
            await apiUploadDocument(file, metadata);
            await loadDocuments();
            return true;
        }
        catch {
            return false;
        }
    };
    const updateDocumentMetadata = async (id, data) => {
        try {
            await updateDocument(id, data);
            await loadDocuments();
            return true;
        }
        catch {
            return false;
        }
    };
    const resubmitDocument = async (id) => {
        try {
            await updateDocument(id, { status: 'pending' });
            await loadDocuments();
            return true;
        }
        catch {
            return false;
        }
    };
    const downloadDocument = async (id) => {
        try {
            const blob = await apiDownloadDocument(id);
            const url = window.URL.createObjectURL(blob);
            const link = document.createElement('a');
            link.href = url;
            link.download = `document-${id}.pdf`;
            document.body.appendChild(link);
            link.click();
            document.body.removeChild(link);
            window.URL.revokeObjectURL(url);
        }
        catch (error) {
            console.warn('Download failed', error);
        }
    };
    const markAllNotificationsRead = async () => {
        try {
            await markAllAsRead();
        }
        catch {
            console.warn('Mark all notifications read failed');
        }
        notifications.value = notifications.value.map((notification) => ({
            ...notification,
            read: true,
        }));
    };
    return {
        team,
        selectedSection,
        dashboardSummary,
        dashboardProgram,
        dashboardTeamName,
        dashboardTeamLead,
        notifications,
        pipeline,
        selectedDocuments,
        pendingRevisions,
        unreadCount,
        loadTeam,
        loadDocuments,
        loadNotifications,
        loadDashboard,
        uploadDocument,
        updateDocumentMetadata,
        resubmitDocument,
        downloadDocument,
        markAllNotificationsRead,
        selectSection,
    };
});
